@FunctionalInterface interface Handler<E extends PaymentEvent> { void handle(E event); }
@FunctionalInterface interface ErrorHandler { void onError(PaymentEvent event, Exception error); }
@FunctionalInterface interface Next { int proceed(PaymentEvent event); }
@FunctionalInterface interface Middleware { int intercept(PaymentEvent event, Next next); }

final class EventBus {
    private final Map<Class<?>, List<Handler<PaymentEvent>>> registry = new ConcurrentHashMap<>();
    private final Map<Class<?>, List<Class<?>>> keyCache = new ConcurrentHashMap<>();
    private final ErrorHandler onError;
    private final Next pipeline;

    EventBus(List<Middleware> middleware, ErrorHandler onError) {
        this.onError = onError;
        Next next = this::deliver;
        for (Middleware m : List.copyOf(middleware).reversed()) {   // reversed(): JDK 21
            Next rest = next;
            next = event -> m.intercept(event, rest);
        }
        this.pipeline = next;
    }

    <E extends PaymentEvent> AutoCloseable subscribe(Class<E> type, Handler<? super E> handler) {
        Handler<PaymentEvent> adapter = event -> handler.handle(type.cast(event));
        List<Handler<PaymentEvent>> handlers = registry.computeIfAbsent(type, t -> new CopyOnWriteArrayList<>());
        handlers.add(adapter);
        return () -> handlers.remove(adapter);
    }

    int publish(PaymentEvent event) { return pipeline.proceed(event); }

    private int deliver(PaymentEvent event) {
        int called = 0;
