                try { handler.handle(event) } catch (e: Exception) { onError.onError(event, e) }
            }
        }
        return called
    }

    private fun dispatchKeys(type: Class<*>): List<KClass<*>> = keyCache.computeIfAbsent(type) { /* the walk */ }
}

